import{_ as e,o as d,c as a,ae as o}from"./chunks/framework.B2ul6ABY.js";const p=JSON.parse('{"title":"MCP Tools — Complete Reference","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/tools.md","filePath":"mcp/tools.md"}'),r={name:"mcp/tools.md"};function c(n,t,i,s,h,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="mcp-tools-—-complete-reference" tabindex="-1">MCP Tools — Complete Reference <a class="header-anchor" href="#mcp-tools-—-complete-reference" aria-label="Permalink to &quot;MCP Tools — Complete Reference&quot;">​</a></h1><p>The MapleSpike MCP server exposes <strong>22 tools</strong> for AI agents to query, search, and verify Canadian government data. All tools return real data from live databases with citations and quality metadata.</p><h2 id="tool-categories" tabindex="-1">Tool Categories <a class="header-anchor" href="#tool-categories" aria-label="Permalink to &quot;Tool Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Tools</th></tr></thead><tbody><tr><td><strong>Data Query</strong></td><td><code>query_gov_data</code>, <code>fact_check</code>, <code>get_citation</code>, <code>latest_releases</code></td></tr><tr><td><strong>Parliamentary</strong></td><td><code>search_committees</code>, <code>search_gazette</code>, <code>search_gic</code>, <code>search_elections</code></td></tr><tr><td><strong>Corporate &amp; Influence</strong></td><td><code>search_corporate</code>, <code>search_influence</code>, <code>search_provincial_lobbying</code></td></tr><tr><td><strong>Legal &amp; Immigration</strong></td><td><code>search_canlii</code>, <code>search_lmia</code>, <code>search_immigration</code>, <code>search_tribunals</code></td></tr><tr><td><strong>Oversight &amp; Science</strong></td><td><code>search_oversight</code>, <code>search_science</code></td></tr><tr><td><strong>Geospatial</strong></td><td><code>search_lode</code></td></tr><tr><td><strong>AI Tools</strong></td><td><code>ai_ask</code>, <code>ai_analyze</code>, <code>ai_search_semantic</code></td></tr><tr><td><strong>System</strong></td><td><code>system_health</code></td></tr></tbody></table><hr><h2 id="_1-query-gov-data" tabindex="-1">1. query_gov_data <a class="header-anchor" href="#_1-query-gov-data" aria-label="Permalink to &quot;1. query_gov_data&quot;">​</a></h2><p>Query Canadian government data releases, datasets, and records across StatCan, CKAN, and provincial portals.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Search keyword (e.g., &quot;GDP&quot;, &quot;housing starts&quot;, &quot;CPI&quot;)</td></tr><tr><td><code>jurisdiction</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>federal</code>, <code>ontario</code>, <code>british-columbia</code>, <code>alberta</code>, <code>quebec</code>, <code>all</code></td></tr><tr><td><code>category</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>economy</code>, <code>demographics</code>, <code>health</code>, <code>justice</code>, <code>environment</code>, <code>education</code>, <code>social</code>, <code>spending</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><p><strong>Response:</strong> <code>{ results: [...], totalCount: number }</code></p><hr><h2 id="_2-fact-check" tabindex="-1">2. fact_check <a class="header-anchor" href="#_2-fact-check" aria-label="Permalink to &quot;2. fact_check&quot;">​</a></h2><p>Check a specific claim, statement, or statistic against official Canadian government data sources (StatCan, open.canada.ca, federal spending records). Returns corroborating or contradicting evidence with citations, trust scores, and confidence ratings.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>claim</code></td><td>string</td><td>Yes</td><td>The claim to fact-check (e.g., &quot;unemployment rate rose to 6.5%&quot;)</td></tr></tbody></table><p><strong>Response:</strong> <code>{ keywords: [...], result: { status, confidence, evidence: [...], summary } }</code></p><hr><h2 id="_3-get-citation" tabindex="-1">3. get_citation <a class="header-anchor" href="#_3-get-citation" aria-label="Permalink to &quot;3. get_citation&quot;">​</a></h2><p>Retrieve a citation record by its SHA-256 content hash. Returns the original data, timestamp, source attribution, and a ready-to-run shell command for independent hash verification.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>hash</code></td><td>string</td><td>Yes</td><td>SHA-256 citation hash (e.g., &quot;sha256-abc123...&quot;)</td></tr></tbody></table><p><strong>Response:</strong> <code>{ citation: { hash, timestamp, source, verified, data }, verifyCommand }</code></p><hr><h2 id="_4-latest-releases" tabindex="-1">4. latest_releases <a class="header-anchor" href="#_4-latest-releases" aria-label="Permalink to &quot;4. latest_releases&quot;">​</a></h2><p>Get the most recent government data releases, economic indicators, and announcements from Statistics Canada and federal/provincial portals.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>category</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Filter by data category</td></tr><tr><td><code>jurisdiction</code></td><td>string</td><td>No</td><td><code>federal</code></td><td>Jurisdiction filter</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>5</code></td><td>Max results (1-20)</td></tr></tbody></table><hr><h2 id="_5-search-committees" tabindex="-1">5. search_committees <a class="header-anchor" href="#_5-search-committees" aria-label="Permalink to &quot;5. search_committees&quot;">​</a></h2><p>Full-text search over House of Commons and Senate committee evidence, meeting transcripts, and proceedings. Covers standing committees (FINA, OGGO, ETHI), special committees, joint committees, and in-camera meeting records.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Search terms (e.g., &quot;carbon tax&quot;, &quot;arrivecan&quot;)</td></tr><tr><td><code>chamber</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>house</code>, <code>senate</code>, <code>joint</code>, <code>all</code></td></tr><tr><td><code>committee</code></td><td>string</td><td>No</td><td>—</td><td>Specific committee code (e.g., &quot;FINA&quot;, &quot;OGGO&quot;, &quot;ETHI&quot;, &quot;SOCI&quot;)</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_6-search-corporate" tabindex="-1">6. search_corporate <a class="header-anchor" href="#_6-search-corporate" aria-label="Permalink to &quot;6. search_corporate&quot;">​</a></h2><p>Search Canadian corporate registry data, federal procurement contracts, lobbying registrations, and executive statements. Tracks insider transactions, sole-source contracts, and corporate-government interactions.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Company name, executive, or keyword</td></tr><tr><td><code>dataset</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>lobbying</code>, <code>procurement</code>, <code>statements</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_7-search-influence" tabindex="-1">7. search_influence <a class="header-anchor" href="#_7-search-influence" aria-label="Permalink to &quot;7. search_influence&quot;">​</a></h2><p>Search influence tracking records including international organizations, NGOs, think tanks, and consultancies operating in Canada. Traces government funding flows, CRA charity status, and grants data.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Organization name or keyword</td></tr><tr><td><code>category</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>international_organization</code>, <code>ngo</code>, <code>think_tank</code>, <code>consultancy</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_8-search-gazette" tabindex="-1">8. search_gazette <a class="header-anchor" href="#_8-search-gazette" aria-label="Permalink to &quot;8. search_gazette&quot;">​</a></h2><p>Search the Canada Gazette — proposed regulations (Part I), enacted regulations (Part II), and Acts of Parliament (Part III). Includes Regulatory Impact Analysis Statements (RIAS).</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Regulation search terms</td></tr><tr><td><code>part</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>part1</code>, <code>part2</code>, <code>part3</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_9-search-gic" tabindex="-1">9. search_gic <a class="header-anchor" href="#_9-search-gic" aria-label="Permalink to &quot;9. search_gic&quot;">​</a></h2><p>Search Governor-in-Council (GiC) appointments to federal agencies, boards, commissions, and Crown corporations. Includes salary ranges, departmental categories, and appointment types.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Appointee name, department, or body</td></tr><tr><td><code>department</code></td><td>string</td><td>No</td><td>—</td><td>Filter by department or portfolio</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_10-search-elections" tabindex="-1">10. search_elections <a class="header-anchor" href="#_10-search-elections" aria-label="Permalink to &quot;10. search_elections&quot;">​</a></h2><p>Search Elections Canada third-party advertiser registry and financial reports. Tracks advertising spending, platforms used, and election periods.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Third-party name, advertiser, or platform</td></tr><tr><td><code>electionPeriod</code></td><td>string</td><td>No</td><td>—</td><td>Filter by election period year or label</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_11-search-provincial-lobbying" tabindex="-1">11. search_provincial_lobbying <a class="header-anchor" href="#_11-search-provincial-lobbying" aria-label="Permalink to &quot;11. search_provincial_lobbying&quot;">​</a></h2><p>Search provincial lobbying registries across Canada. Covers Ontario, BC, Alberta, and Quebec. Cross-references with the federal lobbying registry.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Lobbyist name, organization, or subject</td></tr><tr><td><code>province</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>ontario</code>, <code>british-columbia</code>, <code>alberta</code>, <code>quebec</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_12-search-oversight" tabindex="-1">12. search_oversight <a class="header-anchor" href="#_12-search-oversight" aria-label="Permalink to &quot;12. search_oversight&quot;">​</a></h2><p>Search independent oversight body reports, investigations, and decisions. Covers OAG, PBO, Ethics Commissioner, Lobbying Commissioner, Competition Bureau, and CRTC.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Topic, body, or keyword</td></tr><tr><td><code>body</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>oag</code>, <code>pbo</code>, <code>ethics</code>, <code>lobbying</code>, <code>competition</code>, <code>crtc</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_13-search-canlii" tabindex="-1">13. search_canlii <a class="header-anchor" href="#_13-search-canlii" aria-label="Permalink to &quot;13. search_canlii&quot;">​</a></h2><p>Search Canadian court decisions via CanLII. Covers Supreme Court of Canada, Federal Court, Federal Court of Appeal, and provincial courts.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Case name, party, citation, or keyword</td></tr><tr><td><code>court</code></td><td>string</td><td>No</td><td>—</td><td>Filter by court (e.g., &quot;scc&quot;, &quot;fca&quot;, &quot;onca&quot;, &quot;bcca&quot;)</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_14-search-lmia" tabindex="-1">14. search_lmia <a class="header-anchor" href="#_14-search-lmia" aria-label="Permalink to &quot;14. search_lmia&quot;">​</a></h2><p>Search Labour Market Impact Assessment (LMIA) data from ESDC. Quarterly statistics on employer use of the Temporary Foreign Worker program.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Employer name, occupation, or NOC code</td></tr><tr><td><code>stream</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>high_wage</code>, <code>low_wage</code>, <code>agriculture</code>, <code>caregiver</code>, <code>all</code></td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_15-search-immigration" tabindex="-1">15. search_immigration <a class="header-anchor" href="#_15-search-immigration" aria-label="Permalink to &quot;15. search_immigration&quot;">​</a></h2><p>Search Canadian immigration data including IRCC permanent resident admissions, Express Entry summaries, IRB Refugee Protection Division decisions, and CBSA enforcement statistics.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Country, province, category, or year</td></tr><tr><td><code>source</code></td><td>string</td><td>No</td><td><code>all</code></td><td>Enum: <code>ircc</code>, <code>irb</code>, <code>cbsa</code>, <code>all</code></td></tr><tr><td><code>year</code></td><td>number</td><td>No</td><td>—</td><td>Filter by year</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr></tbody></table><hr><h2 id="_16-search-science" tabindex="-1">16. search_science <a class="header-anchor" href="#_16-search-science" aria-label="Permalink to &quot;16. search_science&quot;">​</a></h2><p>Search Canadian science, space, and research data — CSA missions, Mitacs grants, Ocean Networks Canada observations, Polar Data Catalogue records.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Search term for science/research records</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>20</code></td><td>Max results</td></tr></tbody></table><hr><h2 id="_17-search-tribunals" tabindex="-1">17. search_tribunals <a class="header-anchor" href="#_17-search-tribunals" aria-label="Permalink to &quot;17. search_tribunals&quot;">​</a></h2><p>Search federal tribunal appointments and decisions — GIC appointments to federal tribunals including IRB, CHRT, Competition Tribunal, CITT, Specific Claims Tribunal, and more.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Appointee name, tribunal name, or department</td></tr><tr><td><code>tribunal</code></td><td>string</td><td>No</td><td>—</td><td>Filter by tribunal acronym (e.g., IRB, CHRT, CITT)</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results</td></tr></tbody></table><hr><h2 id="_18-search-lode" tabindex="-1">18. search_lode <a class="header-anchor" href="#_18-search-lode" aria-label="Permalink to &quot;18. search_lode&quot;">​</a></h2><p>Query Statistics Canada LODE (Linkable Open Data Environment) geospatial databases. 12 databases covering addresses, buildings, healthcare, recreation, education, culture, businesses, infrastructure, greenhouses, pedestrian networks, transit networks, and cycling networks.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>No</td><td>—</td><td>Search terms (e.g., &quot;hospitals Ottawa&quot;)</td></tr><tr><td><code>databaseId</code></td><td>string</td><td>No</td><td>—</td><td>Target specific database: <code>oda</code>, <code>odb</code>, <code>odhf</code>, <code>odrsf</code>, <code>odef</code>, <code>odcaf</code>, <code>odbusiness</code>, <code>odi</code>, <code>odg</code>, <code>cpnd</code>, <code>cptnd</code>, <code>ccnd</code></td></tr><tr><td><code>province</code></td><td>string</td><td>No</td><td>—</td><td>Filter by province code (e.g., ON, QC, BC)</td></tr><tr><td><code>municipality</code></td><td>string</td><td>No</td><td>—</td><td>Filter by municipality name</td></tr><tr><td><code>list</code></td><td>boolean</td><td>No</td><td>—</td><td>Set true to list all 12 databases with metadata</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-100)</td></tr></tbody></table><p><strong>12 LODE Databases:</strong></p><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>Records</th><th>Version</th></tr></thead><tbody><tr><td><code>oda</code></td><td>Open Database of Addresses</td><td>~10,000,000</td><td>1.0</td></tr><tr><td><code>odb</code></td><td>Open Database of Buildings</td><td>~14,400,000</td><td>3.0</td></tr><tr><td><code>odhf</code></td><td>Open Database of Healthcare Facilities</td><td>~7,000</td><td>1.1</td></tr><tr><td><code>odrsf</code></td><td>Open Database of Recreational and Sport Facilities</td><td>~182,000</td><td>1.0</td></tr><tr><td><code>odef</code></td><td>Open Database of Educational Facilities</td><td>~19,000</td><td>3.0</td></tr><tr><td><code>odcaf</code></td><td>Open Database of Cultural and Art Facilities</td><td>~8,000</td><td>1.0</td></tr><tr><td><code>odbusiness</code></td><td>Open Database of Businesses</td><td>~500,000</td><td>1.0</td></tr><tr><td><code>odi</code></td><td>Open Database of Infrastructure</td><td>~100,000</td><td>2.0</td></tr><tr><td><code>odg</code></td><td>Open Database of Greenhouses</td><td>~3,900</td><td>2.0</td></tr><tr><td><code>cpnd</code></td><td>Canadian Pedestrian Network Database</td><td>~500,000</td><td>1.0</td></tr><tr><td><code>cptnd</code></td><td>Canadian Public Transit Network Database</td><td>~1,000,000</td><td>1.0</td></tr><tr><td><code>ccnd</code></td><td>Canadian Cycling Network Database</td><td>~250,000</td><td>1.0</td></tr></tbody></table><hr><h2 id="_19-ai-ask" tabindex="-1">19. ai_ask <a class="header-anchor" href="#_19-ai-ask" aria-label="Permalink to &quot;19. ai_ask&quot;">​</a></h2><p>Ask a natural language question about Canadian government data. Uses AI to search across all pipeline sources and return a cited, synthesized answer.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>Natural language question</td></tr><tr><td><code>source_filter</code></td><td>string</td><td>No</td><td>Narrow to specific source type</td></tr></tbody></table><hr><h2 id="_20-ai-analyze" tabindex="-1">20. ai_analyze <a class="header-anchor" href="#_20-ai-analyze" aria-label="Permalink to &quot;20. ai_analyze&quot;">​</a></h2><p>Analyze a document, transcript, or data set using AI. Detects topics, sentiment, entities, and generates a structured summary.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td>string</td><td>Yes</td><td>—</td><td>Text content to analyze</td></tr><tr><td><code>analysis_type</code></td><td>string</td><td>No</td><td><code>full</code></td><td>Enum: <code>summary</code>, <code>entities</code>, <code>sentiment</code>, <code>topics</code>, <code>full</code></td></tr></tbody></table><hr><h2 id="_21-ai-search-semantic" tabindex="-1">21. ai_search_semantic <a class="header-anchor" href="#_21-ai-search-semantic" aria-label="Permalink to &quot;21. ai_search_semantic&quot;">​</a></h2><p>Semantic search across all ingested pipeline data using vector embeddings. Finds conceptually related documents even when keywords don&#39;t match. Uses Qdrant vector DB for similarity search.</p><p><strong>Input Schema:</strong></p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>Yes</td><td>—</td><td>Natural language search query</td></tr><tr><td><code>limit</code></td><td>number</td><td>No</td><td><code>10</code></td><td>Max results (1-50)</td></tr><tr><td><code>source_type</code></td><td>string</td><td>No</td><td>—</td><td>Filter by source type (e.g., &quot;committee&quot;, &quot;lobbying&quot;, &quot;court&quot;)</td></tr></tbody></table><hr><h2 id="_22-system-health" tabindex="-1">22. system_health <a class="header-anchor" href="#_22-system-health" aria-label="Permalink to &quot;22. system_health&quot;">​</a></h2><p>Check the MapleSpike API service health. Returns service status, version, tenant tier, and current API call usage (daily/monthly). No input parameters required.</p>',117)])])}const m=e(r,[["render",c]]);export{p as __pageData,m as default};
